"""dnsmasq configuration: proxy DHCP (next to an existing DHCP server) or a full DHCP server, plus TFTP."""
from __future__ import annotations

import ipaddress

from . import config, db, system


def render() -> str:
    mode = db.get_setting("dhcp_mode")
    itfs = db.get_setting("interfaces") or []
    nets = system.interface_networks()
    uefi = db.get_setting("uefi_loader") or "ipxe.efi"

    lines = [
        "# Generated by PXE Boot Server. Changes here are overwritten; use the web interface.",
        "port=0",
        "bind-dynamic",
        "log-dhcp" if config.DEV else "quiet-dhcp",
    ]
    lines += [f"interface={i}" for i in itfs] or ["# listening on all interfaces"]
    lines += [
        "",
        "enable-tftp",
        f"tftp-root={config.TFTP_DIR}",
        "tftp-port-range=30000,30100",
        "",
        "# Firmware type of the client. Our iPXE loaders contain an embedded script that",
        "# fetches http://<this server>/ipxe/boot.ipxe, so there is no chainload loop.",
        "dhcp-match=set:bios,option:client-arch,0",
        "dhcp-match=set:efi64,option:client-arch,7",
        "dhcp-match=set:efi64,option:client-arch,9",
        "dhcp-match=set:efi32,option:client-arch,6",
        "",
    ]
    if mode == "full":
        start, end = db.get_setting("dhcp_range_start"), db.get_setting("dhcp_range_end")
        lease = db.get_setting("dhcp_lease") or "12h"
        lines.append(f"dhcp-range={start},{end},{lease}")
        if db.get_setting("dhcp_gateway"):
            lines.append(f"dhcp-option=option:router,{db.get_setting('dhcp_gateway')}")
        dns = ",".join(x.strip() for x in (db.get_setting("dhcp_dns") or "").replace(" ", ",").split(",") if x.strip())
        if dns:
            lines.append(f"dhcp-option=option:dns-server,{dns}")
        lines += [
            "dhcp-authoritative",
            "",
            "dhcp-boot=tag:bios,undionly.kpxe",
            f"dhcp-boot=tag:efi64,{uefi}",
            f"dhcp-boot=tag:efi32,{uefi}",
        ]
    else:
        seen = set()
        for _name, itf in nets:
            net = itf.network
            if net.prefixlen >= 31 or str(net) in seen:
                continue
            seen.add(str(net))
            lines.append(f"dhcp-range={net.network_address},proxy,{net.netmask}")
        if not seen:
            lines.append("# no IPv4 network found on the selected interfaces")
        lines += [
            "dhcp-no-override",
            "",
            'pxe-prompt="PXE Boot Server",0',
            'pxe-service=x86PC,"Network boot (BIOS)",undionly.kpxe',
            f'pxe-service=X86-64_EFI,"Network boot (UEFI)",{uefi}',
            f'pxe-service=BC_EFI,"Network boot (UEFI)",{uefi}',
        ]
    return "\n".join(lines) + "\n"


def validate_full_range() -> str | None:
    """Returns an error key when the full DHCP settings are unusable."""
    if db.get_setting("dhcp_mode") != "full":
        return None
    try:
        a = ipaddress.IPv4Address(db.get_setting("dhcp_range_start"))
        b = ipaddress.IPv4Address(db.get_setting("dhcp_range_end"))
    except ValueError:
        return "err_range"
    if a > b:
        return "err_range"
    return None


def apply() -> None:
    config.DNSMASQ_STAGING.parent.mkdir(parents=True, exist_ok=True)
    config.DNSMASQ_STAGING.write_text(render())
    system.helper("apply-dnsmasq")
